const CLIENT_LICENSE_ID=(()=>{try{const c=new URLSearchParams(window.location.search).get("c");return c&&/^[A-Za-z0-9_-]{1,40}$/.test(c)?c:CLIENT_CONFIG.licenseId}catch(e){return CLIENT_CONFIG.licenseId}})();
function applyRemoteConfig(d){
  const ph=v=>String(v||"").replace(/\D/g,"");
  if(d.gymName)S.gym.name=String(d.gymName);
  if(d.code)S.gym.code=String(d.code).toUpperCase().slice(0,2);
  if(d.branch)S.gym.branch=String(d.branch);
  if(ph(d.ownerPhone).length===10)S.staff.Owner.phone=ph(d.ownerPhone);
  if(ph(d.receptionPhone).length===10)S.staff.Reception.phone=ph(d.receptionPhone);
  if(ph(d.trainerPhone).length===10)S.staff.Trainer.phone=ph(d.trainerPhone);
  if(d.ownerEmail)S.staff.Owner.email=String(d.ownerEmail);
  if(d.receptionEmail)S.staff.Reception.email=String(d.receptionEmail);
  if(d.trainerEmail)S.staff.Trainer.email=String(d.trainerEmail);
  saveState();
}
/* ===================== END MULTI-CLIENT SUPPORT ===================== */

