async function verifyLicenseAndStart(){
  const e=window.location.hostname;
  if("file:"===window.location.protocol)document.body.innerHTML='<div style="color:#F87171;padding:32px;text-align:center;font-family:sans-serif"><h2>Offline Copy Detected</h2><p>This software requires a cloud license to run.</p></div>';
  else try{
    const t=db.collection("licenses").doc(CLIENT_LICENSE_ID),a=await t.get();
    if(a.exists){
      const t=a.data();
      if(!0!==t.active)return void(document.body.innerHTML='<div style="color:#F87171;padding:32px;text-align:center;font-family:sans-serif"><h2>License Suspended</h2><p>Please contact the developer to reactivate your software.</p><p style="opacity:.6;font-size:12px">License ID: '+CLIENT_LICENSE_ID+' | active is '+typeof t.active+' ('+String(t.active)+')</p></div>');
      if(t.domain!==e&&"localhost"!==e&&"127.0.0.1"!==e)return void(document.body.innerHTML=`<div style="color:#F87171;padding:32px;text-align:center;font-family:sans-serif"><h2>Unlicensed Domain</h2><p>This app is locked to ${t.domain}.</p></div>`);
      applyRemoteConfig(t);
      await ensureAuthSession();
      render();
    }else document.body.innerHTML='<div style="color:#F87171;padding:32px;text-align:center;font-family:sans-serif"><h2>License Not Found</h2><p>Invalid license ID.</p></div>'
  }catch(e){
    document.body.innerHTML='<div style="padding:32px;text-align:center;font-family:sans-serif"><h2>Connection Error</h2><p>Could not verify license. Please check your internet connection.</p><p style="opacity:.6;font-size:12px">Error code: '+String(e&&(e.code||e.name)||"unknown")+'</p></div>';
    console.error("License check failed:",e);
  }
}

async function ensureAuthSession() {
  if (typeof firebase === 'undefined' || !firebase.auth) return;
  const user = await new Promise(res => { const off = firebase.auth().onAuthStateChanged(u => { off(); res(u); }); });
  if (S.loggedInUser && (!user || user.email !== S.loggedInUser.email)) {
    S.loggedInUser = null; S.screen = "login"; saveState();
  }
}

